package main
import "fmt"
func main() { fmt.Println("Привет, Go") }

package main
import "fmt"
func main() { age := 25; const unit = "лет"; fmt.Println(age, unit) }

package main
import "fmt"
func main() { sum := 0; for i := 1; i <= 3; i++ { sum += i }; if sum == 6 { fmt.Println("готово") } }

package main
import "fmt"
func add(a, b int) int { return a + b }
func main() { fmt.Println(add(2, 3)) }

package main
import ("fmt"; "unicode/utf8")
func main() { s := "Go и мир"; fmt.Println(len(s), utf8.RuneCountInString(s)) }

package main
import "fmt"
func main() { a := []int{2, 4}; a = append(a, 6); fmt.Println(len(a), a[2]) }

package main
import "fmt"
func main() { scores := map[string]int{"Аня": 0}; v, ok := scores["Аня"]; fmt.Println(v, ok) }

package main
import "fmt"
type Task struct { Title string; Done bool }
func main() { t := Task{Title: "Прочитать главу"}; fmt.Println(t.Title, t.Done) }

package main
import "fmt"
type Counter struct { N int }
func (c *Counter) Inc() { c.N++ }
func main() { c := Counter{}; c.Inc(); fmt.Println(c.N) }

package main
import "fmt"
type Speaker interface { Speak() string }
type Cat struct{}
func (Cat) Speak() string { return "мяу" }
func main() { var s Speaker = Cat{}; fmt.Println(s.Speak()) }

package main
import ("errors"; "fmt")
func positive(n int) (int, error) { if n < 0 { return 0, errors.New("отрицательное") }; return n, nil }
func main() { v, err := positive(2); fmt.Println(v, err) }

package main
import "fmt"
func work() { defer fmt.Println("выход"); fmt.Println("работа") }
func main() { work() }

package main
import ("fmt"; "strings")
func main() { fmt.Println(strings.ToUpper("go")) }

package main
import ("fmt"; "os")
func main() { name := "go-demo.txt"; if err := os.WriteFile(name, []byte("hello"), 0600); err != nil { panic(err) }; b, err := os.ReadFile(name); if err != nil { panic(err) }; fmt.Println(string(b)); _ = os.Remove(name) }

package main
import "fmt"
func square(n int) int { return n * n }
func main() { for _, n := range []int{-2, 0, 3} { fmt.Println(square(n)) } }

package main
import ("encoding/json"; "fmt")
type Note struct { Title string; Done bool }
func main() { b, err := json.Marshal(Note{Title: "Go"}); fmt.Println(string(b), err) }

package main
import ("fmt"; "net/http"; "time")
func main() { c := &http.Client{Timeout: time.Second}; fmt.Println(c.Timeout > 0) }

package main
import ("fmt"; "net/http"; "net/http/httptest")
func main() { h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "ok") }); w := httptest.NewRecorder(); h.ServeHTTP(w, httptest.NewRequest("GET", "/", nil)); fmt.Println(w.Code, w.Body.String()) }

package main
import ("fmt"; "os")
func main() { port, ok := os.LookupEnv("APP_PORT"); if !ok { port = "8080" }; fmt.Println(port) }

package main
import ("context"; "fmt"; "time")
func main() { ctx, cancel := context.WithTimeout(context.Background(), time.Millisecond); defer cancel(); <-ctx.Done(); fmt.Println(ctx.Err()) }

package main
import ("fmt"; "sync")
func main() { var wg sync.WaitGroup; wg.Add(1); go func() { defer wg.Done(); fmt.Println("готово") }(); wg.Wait() }

package main
import "fmt"
func main() { ch := make(chan int); go func() { ch <- 7 }(); fmt.Println(<-ch) }

package main
import ("fmt"; "time")
func main() { select { case <-time.After(time.Millisecond): fmt.Println("таймаут") } }

package main
import ("fmt"; "sync")
func main() { var mu sync.Mutex; n := 0; var wg sync.WaitGroup; for i := 0; i < 2; i++ { wg.Add(1); go func() { defer wg.Done(); mu.Lock(); n++; mu.Unlock() }() }; wg.Wait(); fmt.Println(n) }

package main
import ("database/sql"; "fmt")
func main() { var db *sql.DB; fmt.Println(db == nil) }

package main
import "fmt"
type Task struct { ID int; Title string; Done bool }
func main() { t := Task{ID: 1, Title: "Изучить Go"}; fmt.Println(t.ID, t.Title, t.Done) }

package main
import ("fmt"; "net/http"; "net/http/httptest")
func main() { h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.Header().Set("Content-Type", "application/json"); fmt.Fprint(w, "[]") }); w := httptest.NewRecorder(); h.ServeHTTP(w, httptest.NewRequest("GET", "/tasks", nil)); fmt.Println(w.Code, w.Body.String()) }

package main
import ("fmt"; "sync")
type Store struct { mu sync.Mutex; items map[int]string }
func main() { s := Store{items: map[int]string{1: "Go"}}; s.mu.Lock(); fmt.Println(s.items[1]); s.mu.Unlock() }

package main
import ("fmt"; "net/http"; "net/http/httptest")
func main() { h := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(http.StatusCreated) }); w := httptest.NewRecorder(); h.ServeHTTP(w, httptest.NewRequest("POST", "/tasks", nil)); fmt.Println(w.Code) }

package main
import ("fmt"; "runtime")
func main() { fmt.Println("Go", runtime.Version()) }
